CREATE TABLE agents(id UUID NOT NULL,installation_id VARCHAR(100) NOT NULL,hostname VARCHAR(255) NOT NULL,agent_version VARCHAR(50) NOT NULL,os_version VARCHAR(255) NOT NULL,ip_address VARCHAR(45),status VARCHAR(20) NOT NULL,registered_at TIMESTAMP(6) NOT NULL,last_seen_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE(installation_id));
CREATE TABLE agent_event_receipts(id BIGINT NOT NULL AUTO_INCREMENT,agent_id UUID NOT NULL,event_id VARCHAR(100) NOT NULL,event_type VARCHAR(40) NOT NULL,received_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),UNIQUE(agent_id,event_id),FOREIGN KEY(agent_id) REFERENCES agents(id));
